import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import "./App.css";
import Navbar from "./components/Navbar";
import ChatBox from "./components/ChatBox";
import YouTube from "./components/YouTube";
import Wikipedia from "./components/Wikipedia";
import Test from "./components/Test";
import Login from "./components/Auth/Login";
import Register from "./components/Auth/Register";

const App = () => {
  const [activePage, setActivePage] = useState("chat");
  const [messages, setMessages] = useState([]);
  const [latestQuery, setLatestQuery] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [topics, setTopics] = useState([]);
  const [user, setUser] = useState(null); // Track authenticated user

  // Load user authentication state from localStorage
  useEffect(() => {
    const savedUser = JSON.parse(localStorage.getItem("user"));
    if (savedUser) setUser(savedUser);
  }, []);

  // 🔹 Load messages & topics from localStorage on app start
  useEffect(() => {
    const savedMessages = JSON.parse(localStorage.getItem("messages")) || [];
    const savedTopics = JSON.parse(localStorage.getItem("topics")) || [];

    setMessages(savedMessages);
    setTopics(savedTopics);
    setIsLoading(false);
  }, []);

  // 🔹 Save messages to localStorage when updated
  useEffect(() => {
    if (!isLoading && messages.length > 0) {
      localStorage.setItem("messages", JSON.stringify(messages));
    }
  }, [messages, isLoading]);

  // 🔹 Save topics to localStorage when updated
  useEffect(() => {
    if (!isLoading && topics.length > 0) {
      localStorage.setItem("topics", JSON.stringify(topics));
    }
  }, [topics, isLoading]);

  // Logout function
  const handleLogout = () => {
    localStorage.removeItem("user");
    setUser(null);
  };

  return (
    <Router>
      <div className="app-container">
        {user && <Navbar activePage={activePage} setActivePage={setActivePage} onLogout={handleLogout} />}

        <Routes>
          {/* Public Routes */}
          <Route path="/login" element={user ? <Navigate to="/" /> : <Login setUser={setUser} />} />
          <Route path="/register" element={user ? <Navigate to="/" /> : <Register setUser={setUser} />} />

          {/* Protected Routes */}
          {user ? (
            <>
              <Route path="/" element={<ChatBox messages={messages} setMessages={setMessages} setLatestQuery={setLatestQuery} />} />
              <Route path="/youtube" element={<YouTube latestQuery={latestQuery} />} />
              <Route path="/wikipedia" element={<Wikipedia latestQuery={latestQuery} />} />
              <Route path="/test" element={<Test messages={messages} latestQuery={latestQuery} topics={topics} setTopics={setTopics} />} />
            </>
          ) : (
            <Route path="*" element={<Navigate to="/login" />} />
          )}
        </Routes>

        {/* Footer */}
        <footer className="footer">
          <p>&copy; 2025 PAT | @Indrajit002</p>
        </footer>
      </div>
    </Router>
  );
};

export default App;
